scripts.text:
IF ISJSON(@copy_output_json) <> 1 THROW 51000, 'Copy activity output is not JSON.', 1;
IF COALESCE(JSON_VALUE(@copy_output_json, '$.value[0].status'),'') <> 'Succeeded'
 OR JSON_QUERY(@copy_output_json, '$.value[1]') IS NOT NULL
 THROW 51001, 'Expected one successfully completed copy activity.', 1;
DECLARE @rows_read bigint=TRY_CONVERT(bigint,JSON_VALUE(@copy_output_json,'$.value[0].output.rowsRead'));
DECLARE @rows_written bigint=TRY_CONVERT(bigint,JSON_VALUE(@copy_output_json,'$.value[0].output.rowsCopied'));
DECLARE @started varchar(40)=JSON_VALUE(@copy_output_json,'$.value[0].activityRunStart');
DECLARE @ended varchar(40)=JSON_VALUE(@copy_output_json,'$.value[0].activityRunEnd');
IF @rows_read IS NULL OR @rows_written IS NULL OR @rows_read<0 OR @rows_written<0
 OR @started IS NULL OR @ended IS NULL THROW 51002, 'Own copy counts or timestamps unavailable.', 1;
IF EXISTS(SELECT 1 FROM dbo.load_run_audit WHERE run_id=@run_id)
 THROW 51003, 'Audit run already recorded; no overwrite.', 1;
INSERT INTO dbo.load_run_audit (run_id,pipeline_name,status,rows_read,rows_written,accounting_state,start_time_utc,end_time_utc,high_watermark)
VALUES (@run_id,@pipeline_name,'Succeeded',@rows_read,@rows_written,'OBSERVED_COPY_OUTPUT',@started,@ended,NULL);
